"""A utility function to help visualizing boxes."""
def PrintBox(loc: Any, height: Any, width: Any, style: Any = 'r-') -> object {
    (xmin, ymin, xmax, ymax) = (
        (loc[0] * width),
        (loc[1] * height),
        (loc[2] * width),
        (loc[3] * height)
    );
    return [xmin, ymin, xmax, ymax];
}
